/**
 * HMAC (RFC 2104) built on top of the local SHA-256 primitive.
 */
import { sha256, BLOCK_SIZE, DIGEST_SIZE } from './sha256.mjs';

const IPAD = 0x36;
const OPAD = 0x5c;

function concat(a, b) {
  const out = new Uint8Array(a.length + b.length);
  out.set(a, 0);
  out.set(b, a.length);
  return out;
}

/**
 * HMAC-SHA256.
 *
 * @param {Uint8Array} key raw key bytes (any length, including zero)
 * @param {Uint8Array} message raw message bytes
 * @returns {Uint8Array} 32-byte MAC
 */
export function hmacSha256(key, message) {
  const shortened = key.length > BLOCK_SIZE ? sha256(key) : key;

  const inner = new Uint8Array(BLOCK_SIZE);
  const outer = new Uint8Array(BLOCK_SIZE);
  for (let i = 0; i < BLOCK_SIZE; i++) {
    const byte = i < shortened.length ? shortened[i] : 0;
    inner[i] = byte ^ IPAD;
    outer[i] = byte ^ OPAD;
  }

  return sha256(concat(outer, sha256(concat(inner, message))));
}

export const MAC_SIZE = DIGEST_SIZE;

