/**
 * Byte helpers: UTF-8 transcoding and concatenation, mirroring what Python does
 * when it calls `str.encode("utf-8")` / `bytes.decode("utf-8")`.
 */

const encoder = new TextEncoder();
const decoder = new TextDecoder('utf-8', { fatal: true });

/** @param {string} text @returns {Uint8Array} */
export function utf8Encode(text) {
  return encoder.encode(text);
}

/**
 * Strict UTF-8 decode. Throws on malformed input, like Python's default
 * `bytes.decode("utf-8")`.
 *
 * @param {Uint8Array} bytes
 * @returns {string}
 */
export function utf8Decode(bytes) {
  return decoder.decode(bytes);
}

/** @param {...Uint8Array} chunks @returns {Uint8Array} */
export function concatBytes(...chunks) {
  let total = 0;
  for (const chunk of chunks) total += chunk.length;
  const out = new Uint8Array(total);
  let at = 0;
  for (const chunk of chunks) {
    out.set(chunk, at);
    at += chunk.length;
  }
  return out;
}

/** True when `haystack` contains `needle` as a raw byte substring. */
export function bytesContains(haystack, needle) {
  if (needle.length === 0) return true;
  outer: for (let i = 0; i + needle.length <= haystack.length; i++) {
    for (let j = 0; j < needle.length; j++) {
      if (haystack[i + j] !== needle[j]) continue outer;
    }
    return true;
  }
  return false;
}

