/**
 * A JSON codec that matches CPython's `json` module semantics closely enough
 * for byte-identical JOSE segments and byte-identical `print()` output:
 *
 *   - `dumps` behaves like `json.dumps(obj, separators=(",", ":"))`, i.e. it is
 *     compact and `ensure_ascii=True` (every code point above `~` is escaped).
 *   - `loads` preserves key order (Python dicts are insertion-ordered) by
 *     returning `Map` objects, and it keeps the int/float distinction by
 *     returning `BigInt` for integral literals and `Number` for real ones.
 */

/** Order-preserving mapping, standing in for a Python `dict`. */
export function pyDict(entries = []) {
  return new Map(entries);
}

const ESCAPES = new Map([
  [0x5c, '\\\\'],
  [0x22, '\\"'],
  [0x08, '\\b'],
  [0x0c, '\\f'],
  [0x0a, '\\n'],
  [0x0d, '\\r'],
  [0x09, '\\t'],
]);

function hex4(value) {
  return value.toString(16).padStart(4, '0');
}

/** `json.encoder.py_encode_basestring_ascii` */
export function encodeStringAscii(text) {
  let out = '"';
  for (let i = 0; i < text.length; i++) {
    // Iterate by UTF-16 unit: astral characters are emitted as a surrogate
    // pair of \uXXXX escapes, exactly like CPython does with ensure_ascii.
    const code = text.charCodeAt(i);
    const escape = ESCAPES.get(code);
    if (escape !== undefined) {
      out += escape;
    } else if (code >= 0x20 && code <= 0x7e) {
      out += text[i];
    } else {
      out += '\\u' + hex4(code);
    }
  }
  return out + '"';
}

function formatNumber(value) {
  if (typeof value === 'bigint') return value.toString();
  if (!Number.isFinite(value)) {
    return Number.isNaN(value) ? 'NaN' : (value > 0 ? 'Infinity' : '-Infinity');
  }
  if (Number.isInteger(value) && Math.abs(value) < 1e16) {
    // `json.dumps(1.0)` -> "1.0"; float.__repr__ keeps the decimal point.
    return `${value}.0`;
  }
  return String(value);
}

/**
 * @param {*} value Map / plain object / Array / string / number / bigint /
 *                  boolean / null
 * @returns {string} compact JSON text, ASCII only
 */
export function dumps(value, { sortKeys = false } = {}) {
  if (value === null) return 'null';
  if (value === true) return 'true';
  if (value === false) return 'false';
  if (typeof value === 'string') return encodeStringAscii(value);
  if (typeof value === 'number' || typeof value === 'bigint') return formatNumber(value);
  if (Array.isArray(value)) return `[${value.map((item) => dumps(item, { sortKeys })).join(',')}]`;

  const entries = value instanceof Map ? [...value.entries()] : Object.entries(value);
  if (sortKeys) entries.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
  const body = entries
    .map(([key, item]) => `${encodeStringAscii(String(key))}:${dumps(item, { sortKeys })}`)
    .join(',');
  return `{${body}}`;
}

class JsonParser {
  constructor(text) {
    this.text = text;
    this.pos = 0;
  }

  error(message) {
    const err = new Error(`${message}: line 1 column ${this.pos + 1} (char ${this.pos})`);
