    } else if (ch === '\r') {
      out += '\\r';
    } else if (code < 0x20 || code === 0x7f) {
      out += escapeUnprintable(code);
    } else if (code < 0x7f) {
      out += ch;
    } else if (isPrintableCodePoint(ch)) {
      out += ch;
    } else {
      out += escapeUnprintable(code);
    }
  }
  return out + quote;
}

/** `repr()` of a `float`: shortest round-trip digits, always with `.0` or an exponent. */
export function reprFloat(value) {
  if (Number.isNaN(value)) return 'nan';
  if (!Number.isFinite(value)) return value > 0 ? 'inf' : '-inf';
  if (value === 0) return Object.is(value, -0) ? '-0.0' : '0.0';

  const negative = value < 0;
  const [mantissa, exponentText] = Math.abs(value).toExponential().split('e');
  const digits = mantissa.replace('.', '');
  const decpt = parseInt(exponentText, 10) + 1;

  let out;
  if (decpt <= -4 || decpt > 16) {
    // CPython switches to scientific notation outside this window.
    const head = digits.length > 1 ? `${digits[0]}.${digits.slice(1)}` : digits;
    const exponent = decpt - 1;
    const sign = exponent < 0 ? '-' : '+';
    out = `${head}e${sign}${String(Math.abs(exponent)).padStart(2, '0')}`;
  } else if (decpt <= 0) {
    out = `0.${'0'.repeat(-decpt)}${digits}`;
  } else if (decpt >= digits.length) {
    out = `${digits}${'0'.repeat(decpt - digits.length)}.0`;
  } else {
    out = `${digits.slice(0, decpt)}.${digits.slice(decpt)}`;
  }
