/**
 * A focused re-implementation of the slice of `argparse` this program needs:
 * long options with a single value, `--opt=value`, unique-prefix abbreviation,
 * `-h/--help`, required-argument enforcement and the exact usage/error text
 * (including exit statuses 0 for help and 2 for a usage error).
 */

// argparse._negative_number_matcher
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

const HELP_TEXT = 'show this help message and exit';
const MAX_HELP_POSITION = 24;
const INDENT = 2;

class ArgumentError extends Error {}

export class ArgumentParser {
  /** @param {{prog: string}} options */
  constructor({ prog }) {
    this.prog = prog;
    /** @type {Array<{optionStrings: string[], dest: string, metavar: string|null, required: boolean, action: string, help: string|null}>} */
    this.actions = [];
    this.addArgument(['-h', '--help'], { action: 'help', help: HELP_TEXT });
  }

  addArgument(optionStrings, { action = 'store', required = false, metavar = null, help = null } = {}) {
    const longest = optionStrings.find((s) => s.startsWith('--')) ?? optionStrings[0];
    const dest = longest.replace(/^-+/, '').replace(/-/g, '_');
    this.actions.push({
      optionStrings,
      dest,
      metavar: metavar ?? (action === 'store' ? dest.toUpperCase() : null),
      required,
      action,
      help,
    });
  }

  /** `--payload PAYLOAD` / `-h` — the form used in the usage line. */
  #usageFragment(action) {
    const primary = action.optionStrings[action.optionStrings.length - 1] === '--help'
      ? '-h'
      : action.optionStrings[0];
    return action.action === 'store' ? `${primary} ${action.metavar}` : primary;
  }

  /** `-h, --help` / `--payload PAYLOAD` — the form used in the options list. */
  #invocation(action) {
    if (action.action !== 'store') return action.optionStrings.join(', ');
    return action.optionStrings.map((s) => `${s} ${action.metavar}`).join(', ');
  }

  formatUsage() {
    const parts = this.actions.map((action) => {
      const fragment = this.#usageFragment(action);
      return action.required ? fragment : `[${fragment}]`;
    });
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  formatHelp() {
    const invocations = this.actions.map((action) => this.#invocation(action));
    const actionMaxLength = Math.max(...invocations.map((s) => s.length)) + INDENT;
    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
    const actionWidth = helpPosition - INDENT - 2;

    let out = `${this.formatUsage()}\noptions:\n`;
    for (const [index, action] of this.actions.entries()) {
      const invocation = invocations[index];
      if (!action.help) {
        out += `${' '.repeat(INDENT)}${invocation}\n`;
      } else if (invocation.length <= actionWidth) {
        out += `${' '.repeat(INDENT)}${invocation.padEnd(actionWidth)}  ${action.help}\n`;
      } else {
        out += `${' '.repeat(INDENT)}${invocation}\n${' '.repeat(helpPosition)}${action.help}\n`;
      }
    }
    return out;
  }

  /** Prints usage plus the message to stderr and exits with status 2. */
  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  #optionStringActions() {
    const map = new Map();
    for (const action of this.actions) {
      for (const optionString of action.optionStrings) map.set(optionString, action);
    }
    return map;
  }

  /**
   * argparse._parse_optional: decide whether a token is an option, and if so
   * which one, plus any `=`-attached value.
   *
   * @returns {null | {action: object|null, optionString: string, explicitArg: string|null}}
   *          `null` means "this is a plain value, not an option".
   */
  #parseOptional(argString) {
    const known = this.#optionStringActions();
    if (!argString) return null;
    if (!argString.startsWith('-')) return null;
    if (known.has(argString)) {
      return { action: known.get(argString), optionString: argString, explicitArg: null };
    }
    if (argString.length === 1) return null;

    const equals = argString.indexOf('=');
    if (equals !== -1) {
      const optionString = argString.slice(0, equals);
      if (known.has(optionString)) {
        return { action: known.get(optionString), optionString, explicitArg: argString.slice(equals + 1) };
      }
    }

    const matches = this.#optionTuples(argString, known);
    if (matches.length > 1) {
      const options = matches.map((m) => m.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    } else if (matches.length === 1) {
      return matches[0];
    }

    // A lone negative number is a value, since no option looks like one here.
    if (NEGATIVE_NUMBER.test(argString)) return null;
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, explicitArg: null };
  }

  /** argparse._get_option_tuples: unique-prefix abbreviation for long options. */
  #optionTuples(argString, known) {
    if (!argString.startsWith('--')) return [];
    const equals = argString.indexOf('=');
    const prefix = equals === -1 ? argString : argString.slice(0, equals);
    const explicitArg = equals === -1 ? null : argString.slice(equals + 1);

    const matches = [];
    for (const [optionString, action] of known) {
      if (optionString.startsWith(prefix)) matches.push({ action, optionString, explicitArg });
    }
    return matches;
  }

  /**
   * @param {string[]} argv arguments after the program name
   * @returns {Map<string, string>} dest -> value
   */
  parseArgs(argv) {
    const values = new Map();
    const seen = new Set();
    const extras = [];

    for (let i = 0; i < argv.length; i++) {
      const optional = this.#parseOptional(argv[i]);
      if (optional === null) {
        // No positionals are defined, so any bare value is unrecognized.
        extras.push(argv[i]);
        continue;
      }

      const { action, optionString, explicitArg } = optional;
      if (action === null) {
        extras.push(argv[i]);
        continue;
      }

      if (action.action === 'help') {
        process.stdout.write(this.formatHelp());
        process.exit(0);
      }

      let value = explicitArg;
      if (value === null) {
        const next = i + 1 < argv.length ? argv[i + 1] : undefined;
        if (next !== undefined && this.#parseOptional(next) === null) {
          value = next;
          i++;
        } else {
          this.error(`argument ${optionString}: expected one argument`);
        }
      }
      values.set(action.dest, value);
      seen.add(action.dest);
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action.dest))
      .map((action) => action.optionStrings[action.optionStrings.length - 1]);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return values;
  }
}

