/**
 * HMAC key handling, including the guard that refuses secrets which are really
 * asymmetric keys or certificates.
 */
import { hmacSha256 } from '../digest/hmac.mjs';
import { utf8Encode, bytesContains } from '../bytes.mjs';
import { JWKError } from './errors.mjs';
import { ALGORITHMS, HMAC_ALGORITHMS } from './algorithms.mjs';

/**
 * Text that must never appear anywhere inside an HMAC secret. Determined from
 * the reference implementation's observable behaviour: the check is a
 * case-sensitive raw substring test over the UTF-8 encoded secret.
 */
const INVALID_KEY_MARKERS = [
  '-----BEGIN PUBLIC KEY-----',
  '-----BEGIN RSA PUBLIC KEY-----',
  '-----BEGIN PRIVATE KEY-----',
  '-----BEGIN RSA PRIVATE KEY-----',
  '-----BEGIN EC PRIVATE KEY-----',
  '-----BEGIN DSA PRIVATE KEY-----',
  '-----BEGIN OPENSSH PRIVATE KEY-----',
  '-----BEGIN ENCRYPTED PRIVATE KEY-----',
  '-----BEGIN SSH2 PUBLIC KEY-----',
  '-----BEGIN SSH2 ENCRYPTED PRIVATE KEY-----',
  '-----BEGIN CERTIFICATE-----',
  '-----BEGIN TRUSTED CERTIFICATE-----',
  '-----BEGIN CERTIFICATE REQUEST-----',
  '-----BEGIN NEW CERTIFICATE REQUEST-----',
  '-----BEGIN X509 CRL-----',
  '-----BEGIN DH PARAMETERS-----',
  'ssh-rsa',
  'ssh-dss',
  'ssh-ed25519',
  'ecdsa-sha2-nistp256',
  'ecdsa-sha2-nistp384',
  'ecdsa-sha2-nistp521',
].map((marker) => utf8Encode(marker));

const ASYMMETRIC_KEY_MESSAGE =
  'The specified key is an asymmetric key or x509 certificate and should not be used as an HMAC secret.';

export class HMACKey {
  /**
   * @param {string|Uint8Array} key the shared secret
   * @param {string} algorithm one of the HS* algorithms
   */
  constructor(key, algorithm) {
    if (!HMAC_ALGORITHMS.has(algorithm)) {
      throw new JWKError(`hash_alg: ${algorithm} is not a valid hash algorithm`);
    }
    if (algorithm !== ALGORITHMS.HS256) {
      throw new JWKError(`${algorithm} is not supported by this backend`);
    }
    if (typeof key !== 'string' && !(key instanceof Uint8Array)) {
      throw new JWKError('Expected a string key');
    }

    this.algorithm = algorithm;
    this.preparedKey = typeof key === 'string' ? utf8Encode(key) : key;

    for (const marker of INVALID_KEY_MARKERS) {
      if (bytesContains(this.preparedKey, marker)) {
        throw new JWKError(ASYMMETRIC_KEY_MESSAGE);
      }
    }
  }

  /**
   * @param {Uint8Array} message the signing input
   * @returns {Uint8Array} the raw MAC
   */
  sign(message) {
    return hmacSha256(this.preparedKey, message);
  }
}

/**
 * `jose.jwk.construct` for the HMAC case.
 *
 * @param {string|Uint8Array|HMACKey} key
 * @param {string} algorithm
 * @returns {HMACKey}
 */
export function construct(key, algorithm) {
  if (key instanceof HMACKey) return key;
  return new HMACKey(key, algorithm);
}

