      throw new JWKError(`${algorithm} is not supported by this backend`);
    }
    if (typeof key !== 'string' && !(key instanceof Uint8Array)) {
      throw new JWKError('Expected a string key');
    }

    this.algorithm = algorithm;
    this.preparedKey = typeof key === 'string' ? utf8Encode(key) : key;

    for (const marker of INVALID_KEY_MARKERS) {
      if (bytesContains(this.preparedKey, marker)) {
        throw new JWKError(ASYMMETRIC_KEY_MESSAGE);
      }
    }
  }

  /**
   * @param {Uint8Array} message the signing input
   * @returns {Uint8Array} the raw MAC
   */
  sign(message) {
    return hmacSha256(this.preparedKey, message);
  }
}

/**
 * `jose.jwk.construct` for the HMAC case.
 *
 * @param {string|Uint8Array|HMACKey} key
 * @param {string} algorithm
 * @returns {HMACKey}
 */
export function construct(key, algorithm) {
  if (key instanceof HMACKey) return key;
  return new HMACKey(key, algorithm);
}

