import { base64UrlEncode, base64UrlDecode } from '../base64url.mjs';
import { utf8Encode, utf8Decode } from '../bytes.mjs';
import { dumps } from '../python/json.mjs';
import { construct } from './jwk.mjs';
import { JWSError, JWKError } from './errors.mjs';
import { ALGORITHMS, SUPPORTED } from './algorithms.mjs';

/** Builds the protected header segment. Header keys are serialized sorted. */
function encodeHeader(algorithm, additionalHeaders) {
  const header = new Map([
    ['typ', 'JWT'],
    ['alg', algorithm],
  ]);
  if (additionalHeaders) {
    for (const [key, value] of additionalHeaders instanceof Map
      ? additionalHeaders
      : Object.entries(additionalHeaders)) {
      header.set(key, value);
    }
  }
  return base64UrlEncode(utf8Encode(dumps(header, { sortKeys: true })));
}

/** Builds the payload segment; mappings are serialized as compact JSON. */
function encodePayload(payload) {
  if (payload instanceof Uint8Array) return base64UrlEncode(payload);
  if (typeof payload === 'string') return base64UrlEncode(utf8Encode(payload));
  return base64UrlEncode(utf8Encode(dumps(payload)));
}

function signHeaderAndClaims(encodedHeader, encodedPayload, algorithm, key) {
  const signingInput = `${encodedHeader}.${encodedPayload}`;
  let signature;
  try {
    signature = construct(key, algorithm).sign(utf8Encode(signingInput));
  } catch (err) {
    if (err instanceof JWKError) {
      const wrapped = new JWSError(err.message);
      wrapped.cause = err;
      throw wrapped;
    }
    throw err;
  }
  return `${signingInput}.${base64UrlEncode(signature)}`;
}

