 * `jose.jws.sign`.
 *
 * @param {Map|object|Uint8Array|string} payload
 * @param {string|Uint8Array} key
 * @param {{headers?: Map|object|null, algorithm?: string}} [options]
 * @returns {string} the compact JWS
 */
export function sign(payload, key, { headers = null, algorithm = ALGORITHMS.HS256 } = {}) {
  if (!SUPPORTED.has(algorithm)) {
    throw new JWSError(`Algorithm ${algorithm} not supported.`);
  }
  return signHeaderAndClaims(encodeHeader(algorithm, headers), encodePayload(payload), algorithm, key);
}

