export function getUnverifiedHeaderText(token) {
  return utf8Decode(getUnverifiedHeaderBytes(token));
}

/** Convenience: the payload bytes decoded as UTF-8 text. */
export function getUnverifiedClaimsText(token) {
  return utf8Decode(getUnverifiedClaimsBytes(token));
