/**
 * Synchronous stdout/stderr writers.
 *
 * `process.stdout.write` is asynchronous for pipes, which can truncate output
 * when the process exits right afterwards (as argparse does on a usage error),
 * so everything goes through `fs.writeSync` instead.
 */
import { writeSync } from 'node:fs';
import { utf8Encode } from '../bytes.mjs';

function writeAll(fd, text) {
  const bytes = utf8Encode(text);
  let offset = 0;
  while (offset < bytes.length) {
    try {
      offset += writeSync(fd, bytes, offset, bytes.length - offset);
    } catch (err) {
      if (err.code === 'EAGAIN') continue; // non-blocking pipe, retry
      if (err.code === 'EPIPE') return; // reader went away
      throw err;
    }
  }
}

/** @param {string} text */
export function writeStdout(text) {
  writeAll(1, text);
}

/** @param {string} text */
export function writeStderr(text) {
  writeAll(2, text);
}

