/**
 * Renders a CPython-style traceback for an unhandled error, so a failing run
 * looks like the original frozen script's failure (stderr text, empty stdout,
 * exit status 1).
 *
 * The frame lists are fixed descriptions of the reference call stacks; there is
 * no way to recover Python source locations from JavaScript, and the reference
 * build reports them without source lines because it is frozen.
 */
import { writeStderr } from './stdio.mjs';

/** Call stack the reference reports for the failing HMAC key construction. */
export const JWK_CONSTRUCT_FRAMES = [
  { file: 'jose/jws.py', line: 164, name: '_sign_header_and_claims' },
  { file: 'jose/jwk.py', line: 79, name: 'construct' },
  { file: 'jose/backends/cryptography_backend.py', line: 544, name: '__init__' },
];

/** Call stack the reference reports for the re-raised signing error. */
export const JWT_ENCODE_FRAMES = [
  { file: 'test8.py', line: 15, name: '<module>' },
  { file: 'jose/jwt.py', line: 63, name: 'encode' },
  { file: 'jose/jws.py', line: 47, name: 'sign' },
  { file: 'jose/jws.py', line: 167, name: '_sign_header_and_claims' },
];

const CHAINED_MESSAGE = 'During handling of the above exception, another exception occurred:';

function formatSection({ frames, error }) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of frames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
  }
  lines.push(`${error.name}: ${error.message}`);
  return `${lines.join('\n')}\n`;
}

/**
 * @param {Array<{frames: Array<object>, error: Error}>} sections oldest first
 * @param {string} scriptName name used in the frozen-bootloader footer
 */
export function printTraceback(sections, scriptName) {
  const rendered = sections.map(formatSection);
  writeStderr(rendered.join(`\n${CHAINED_MESSAGE}\n\n`));
  // The frozen bootloader appends this line, tagged with its own process id.
  writeStderr(`[PYI-${process.pid % 1000}:ERROR] Failed to execute script '${scriptName}' due to unhandled exception!\n`);
}

