/**
 * CPython `repr()` for the value shapes that come out of `json.loads`, so that
 * `print(some_dict)` can be reproduced byte for byte.
 */

/**
 * Mirrors `str.isprintable()`: everything is printable except the general
 * categories Cc, Cf, Cs, Co, Cn, Zl, Zp and Zs — with U+0020 special-cased as
 * printable.
 */
const NON_PRINTABLE = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;

function isPrintableCodePoint(ch) {
  if (ch === ' ') return true;
  return !NON_PRINTABLE.test(ch);
}

function escapeUnprintable(code) {
  if (code < 0x100) return '\\x' + code.toString(16).padStart(2, '0');
  if (code < 0x10000) return '\\u' + code.toString(16).padStart(4, '0');
  return '\\U' + code.toString(16).padStart(8, '0');
}

/**
 * `repr()` of a `str`: single quotes by default, double quotes only when the
 * text holds a single quote but no double quote.
 *
 * @param {string} text
 * @returns {string}
 */
export function reprString(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";

  let out = quote;
  for (const ch of text) {
    const code = ch.codePointAt(0);
    if (ch === quote || ch === '\\') {
      out += '\\' + ch;
    } else if (ch === '\t') {
      out += '\\t';
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (code < 0x20 || code === 0x7f) {
      out += escapeUnprintable(code);
    } else if (code < 0x7f) {
      out += ch;
    } else if (isPrintableCodePoint(ch)) {
      out += ch;
    } else {
      out += escapeUnprintable(code);
    }
  }
  return out + quote;
}

/** `repr()` of a `float`: shortest round-trip digits, always with `.0` or an exponent. */
export function reprFloat(value) {
  if (Number.isNaN(value)) return 'nan';
  if (!Number.isFinite(value)) return value > 0 ? 'inf' : '-inf';
  if (value === 0) return Object.is(value, -0) ? '-0.0' : '0.0';

  const negative = value < 0;
  const [mantissa, exponentText] = Math.abs(value).toExponential().split('e');
  const digits = mantissa.replace('.', '');
  const decpt = parseInt(exponentText, 10) + 1;

  let out;
  if (decpt <= -4 || decpt > 16) {
    // CPython switches to scientific notation outside this window.
    const head = digits.length > 1 ? `${digits[0]}.${digits.slice(1)}` : digits;
    const exponent = decpt - 1;
    const sign = exponent < 0 ? '-' : '+';
    out = `${head}e${sign}${String(Math.abs(exponent)).padStart(2, '0')}`;
  } else if (decpt <= 0) {
    out = `0.${'0'.repeat(-decpt)}${digits}`;
  } else if (decpt >= digits.length) {
    out = `${digits}${'0'.repeat(decpt - digits.length)}.0`;
  } else {
    out = `${digits.slice(0, decpt)}.${digits.slice(decpt)}`;
  }
  return negative ? `-${out}` : out;
}

/**
 * `repr()` for dicts (`Map`), lists (`Array`), strings, ints (`BigInt`),
 * floats (`Number`), booleans and `None` (`null`).
 *
 * @param {*} value
 * @returns {string}
 */
export function pyRepr(value) {
  if (value === null || value === undefined) return 'None';
  if (value === true) return 'True';
  if (value === false) return 'False';
  if (typeof value === 'string') return reprString(value);
  if (typeof value === 'bigint') return value.toString();
  if (typeof value === 'number') return reprFloat(value);
  if (Array.isArray(value)) return `[${value.map(pyRepr).join(', ')}]`;
  if (value instanceof Map) {
    const body = [...value.entries()]
      .map(([key, item]) => `${pyRepr(key)}: ${pyRepr(item)}`)
      .join(', ');
    return `{${body}}`;
  }
  const body = Object.entries(value)
    .map(([key, item]) => `${pyRepr(key)}: ${pyRepr(item)}`)
    .join(', ');
  return `{${body}}`;
}

/** `print(value)` for a single argument. */
export function pyPrint(value) {
  process.stdout.write(`${typeof value === 'string' ? value : pyRepr(value)}\n`);
}

