/**
 * Node.js port of /workspace/dataset/jose/test8.py
 *
 * Demonstrates `jwt.get_unverified_claims` / `jwt.get_unverified_header`, which
 * read a token's contents without verifying its signature (potentially unsafe).
 */
import { ArgumentParser } from './lib/python/argparse.mjs';
import { pyDict } from './lib/python/json.mjs';
import { pyPrint } from './lib/python/repr.mjs';
import {
  printTraceback,
  JWK_CONSTRUCT_FRAMES,
  JWT_ENCODE_FRAMES,
} from './lib/python/traceback.mjs';
import * as jwt from './lib/jose/jwt.mjs';

// argparse derives the program name from basename(sys.argv[0]); the reference
// build is invoked as `test8_executable`, so usage/error text uses that name.
const PROG = 'test8_executable';

const parser = new ArgumentParser({ prog: PROG });
parser.addArgument(['--payload'], { required: true });
parser.addArgument(['--secret'], { required: true });
const args = parser.parseArgs(process.argv.slice(2));

const secret = args.get('secret');
const payload = pyDict([['data', args.get('payload')]]);

// Create the token.
let token;
try {
  token = jwt.encode(payload, secret);
} catch (err) {
  printTraceback(
    [
      { frames: JWK_CONSTRUCT_FRAMES, error: err.cause ?? err },
      { frames: JWT_ENCODE_FRAMES, error: err },
    ],
    'test8',
  );
  process.exit(1);
}
pyPrint(token);

// Read the claims without verifying the signature.
const claims = jwt.getUnverifiedClaims(token);
pyPrint(claims);

// Read the header without verifying the signature.
const header = jwt.getUnverifiedHeader(token);
pyPrint(header);

